#!/usr/bin/env node
// Guarantees extension/build-info.js exists, WITHOUT overwriting a real one.
// The file is gitignored (generated by `npm run build`), but
// extension/background.js statically imports it, and a missing static import
// stops the whole MV3 service worker from registering. This writes the null
// stub on a fresh clone (run from `npm install`'s postinstall) so "clone,
// npm install, load unpacked" works before the first build.
import { existsSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const target = join(dirname(fileURLToPath(import.meta.url)), '..', 'extension', 'build-info.js');
if (!existsSync(target)) {
  writeFileSync(target, 'self.GHAX_BUILD_INFO = null;\n');
}
